set -euo pipefail

REPOSITORY_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TEST_ROOT="$(mktemp -d "${TMPDIR:-/tmp}/rdf4j-vector-launchers.XXXXXX")"
trap 'rm -rf "${TEST_ROOT}"' EXIT

make_fake_java() {
	local destination=$1
	cat >"${destination}" <<'FAKE_JAVA'
#!/usr/bin/env bash
set -euo pipefail
if [[ ${1:-} == "--list-modules" ]]; then
	if [[ ${FAKE_VECTOR_MODULE:-absent} == "present" ]]; then
		echo "jdk.incubator.vector@25"
	fi
	exit 0
fi
printf '%s\n' "$@" >"${FAKE_JAVA_CAPTURE}"
FAKE_JAVA
	chmod +x "${destination}"
}

assert_module_argument() {
	local capture=$1
	local expectation=$2
	if [[ ${expectation} == "present" ]]; then
		grep -Fqx -- "--add-modules=jdk.incubator.vector" "${capture}"
	elif grep -Fqx -- "--add-modules=jdk.incubator.vector" "${capture}"; then
		echo "Vector module argument was added for a runtime that does not provide it" >&2
		exit 1
	fi
}

run_server_case() {
	local module_state=$1
	local case_root="${TEST_ROOT}/server-${module_state}"
	mkdir -p "${case_root}/bin" "${case_root}/lib"
	cp "${REPOSITORY_ROOT}/tools/server-boot/src/main/dist/bin/rdf4j-server.sh" "${case_root}/bin/"
	touch "${case_root}/lib/rdf4j-server-boot-test.jar"
	make_fake_java "${case_root}/fake-java"
	FAKE_VECTOR_MODULE=${module_state} \
		FAKE_JAVA_CAPTURE="${case_root}/arguments.txt" \
		JAVA_CMD="${case_root}/fake-java" \
		bash "${case_root}/bin/rdf4j-server.sh" >/dev/null
	assert_module_argument "${case_root}/arguments.txt" "${module_state}"
}

run_console_case() {
	local module_state=$1
	local case_root="${TEST_ROOT}/console-${module_state}"
	mkdir -p "${case_root}/bin" "${case_root}/lib"
	cp "${REPOSITORY_ROOT}/assembly/src/main/dist/console.sh" "${case_root}/bin/"
	touch "${case_root}/lib/rdf4j-console-test.jar"
	make_fake_java "${case_root}/fake-java"
	FAKE_VECTOR_MODULE=${module_state} \
		FAKE_JAVA_CAPTURE="${case_root}/arguments.txt" \
		JAVA_CMD="${case_root}/fake-java" \
		sh "${case_root}/bin/console.sh" >/dev/null
	assert_module_argument "${case_root}/arguments.txt" "${module_state}"
}

for module_state in present absent; do
	run_server_case "${module_state}"
	run_console_case "${module_state}"
done

grep -Fq -- "--add-modules=jdk.incubator.vector" "${REPOSITORY_ROOT}/assembly/src/main/dist/console.bat"
grep -Fq -- "--add-modules=jdk.incubator.vector" "${REPOSITORY_ROOT}/docker/Dockerfile-tomcat"
grep -Fq -- "--add-modules=jdk.incubator.vector" "${REPOSITORY_ROOT}/docker/Dockerfile-jetty"
